head.script:
scwin.trigger2_onclick = function(e) {
    scwin.$w.executeSubmission("submission1");
};
scwin.trigger3_onclick = function(e) {
    log = $w.getSubmission("submission1");
    //alert($w.getSubmission("submission1"));
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. chrome에서 샘플실행 후 F12로 모바일기기모드로 변경한다.(타 브라우저는 제외)
    //1. Run the sample in chrome and change to mobile mode with F12 (except for other browsers).
    //Verify 1. The chrome browser changes to mobile device mode.
    //Test step2. '$w.getSubmission('submission1')'버튼을 클릭한다. 또는 console에서 $w.getSubmission('submission1')입력하여 확인한다.
    //2. Click the '$ w.getSubmission (' submission1 ')' button. Or, type $ w.getSubmission ('submission1') at console to confirm.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log != undefined", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
